import numpy as np, pandas as pd
z=np.load('resid_placebo.npz'); rD,rY,rP,D=z['rD'],z['rY'],z['rP'],z['D']
def loclin(d0,h,ry=rY,quad=False):
    u=(D-d0)/h; w=np.clip(1-np.abs(u)**3,0,None)**3; m=w>0
    cols=[np.ones(m.sum()),rD[m]]+([rD[m]**2] if quad else [])
    Xm=np.column_stack(cols); W=w[m]
    A=(Xm.T*W)@Xm; b=np.linalg.solve(A,(Xm.T*W)@ry[m])
    res=ry[m]-Xm@b; s2=np.sum(W*res**2)/np.sum(W)*m.sum()/(m.sum()-len(b))
    cov=s2*np.linalg.inv(A)
    if quad:
        # derivative at d0 wrt D: slope = b1 + 2*b2*E[rD|d0]
        mrD=np.sum(W*rD[m])/np.sum(W)
        sl=b[1]+2*b[2]*mrD
        g=np.array([0,1,2*mrD]); se=np.sqrt(g@cov@g)
        return sl,se,m.sum()
    return b[1],np.sqrt(cov[1,1]),m.sum()
print('local LINEAR (global nuisances, placebo-controlled):')
for d0 in [4.5,5,5.5]:
    for h in [1.5,2,2.5]:
        b,se,n=loclin(d0,h); bp,sep,_=loclin(d0,h,ry=rP)
        print(f'  d0={d0} h={h}: slope={b:+.4f}({se:.4f}) 2day={-2*b:+.4f} CI[{ -2*(b+1.96*se):+.4f},{-2*(b-1.96*se):+.4f}] placebo={bp:+.4f}({sep:.4f})')
print('local QUADRATIC (allows curvature):')
for d0 in [5]:
    for h in [2,2.5,3]:
        b,se,n=loclin(d0,h,quad=True); bp,sep,_=loclin(d0,h,ry=rP,quad=True)
        print(f'  d0={d0} h={h}: slope={b:+.4f}({se:.4f}) 2day={-2*b:+.4f} placebo_slope={bp:+.4f}({sep:.4f})')
